"""Deterministic, self-contained HTML animation player compiler."""
import base64
import html
import json
from dataclasses import asdict


def compile_html(resolved_animation) -> bytes:
    shots=[]
    for shot in resolved_animation.shots:
        asset=resolved_animation.assets[shot["source_id"]]
        art=asset.get("artwork_data_url")
        if not art: raise ValueError("Resolved artwork is missing.")
        text={key:asset["text_data_urls"][key] for key in asset.get("text_layers",{}) if key in asset.get("text_data_urls",{})}
        shots.append({**shot,"art":art,"text_images":text,"text_ids":list(text)})
    data=json.dumps({"name":resolved_animation.name,"width":resolved_animation.aspect_width,"height":resolved_animation.aspect_height,"duration":resolved_animation.duration_ms,"shots":shots},sort_keys=True,separators=(",",":"),ensure_ascii=False).replace("</","<\\/")
    source=r'''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>
*{box-sizing:border-box}body{margin:0;background:#171717;color:#fff;font:16px system-ui,sans-serif;display:grid;min-height:100vh;place-items:center}.player{width:min(96vw,1200px)}canvas{display:block;width:100%;aspect-ratio:__RATIO__;background:#000}.controls{display:flex;gap:.5rem;align-items:center;padding:.5rem 0;flex-wrap:wrap}button,input,select{font:inherit}button{background:#333;color:white;border:1px solid #777;border-radius:.35rem;padding:.35rem .65rem}input[type=range]{flex:1;min-width:150px}output{font-variant-numeric:tabular-nums}.error{color:#ffb0a0}
</style><main class="player"><canvas aria-label="Animation playback"></canvas><div class="controls"><button id="play">Play</button><button id="restart">Restart</button><button id="prev">Previous shot</button><button id="next">Next shot</button><input id="seek" type="range" min="0" max="__DURATION__" value="0" aria-label="Seek"><output id="time">0:00 / 0:00</output><select id="speed" aria-label="Playback speed"><option>0.5</option><option selected>1</option><option>1.5</option><option>2</option></select><label><input id="loop" type="checkbox"> Loop</label><button id="full">Fullscreen</button></div><p id="error" class="error" role="status"></p></main><script>
const A=__DATA__,canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),seek=document.querySelector('#seek'),timeOut=document.querySelector('#time'),play=document.querySelector('#play'),err=document.querySelector('#error');let images=new Map(),t=0,playing=false,last=0,raf=0;
function image(url){if(!images.has(url)){const im=new Image();im.src=url;images.set(url,im)}return images.get(url)}
const all=[];for(const s of A.shots){all.push(image(s.art));for(const u of Object.values(s.text_images||{}))all.push(image(u))}
Promise.all(all.map(im=>new Promise((ok,no)=>{if(im.complete&&im.naturalWidth)return ok();im.onload=ok;im.onerror=()=>no(Error('An embedded scene image could not be decoded.'))}))).then(draw).catch(e=>err.textContent=e.message);
function fit(){const dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);return[w,h]}
function state(keys,at,fields,defaults){if(!keys?.length)return defaults;if(at<=keys[0].time_ms)return Object.fromEntries(fields.map(k=>[k,keys[0][k]]));if(at>=keys.at(-1).time_ms)return Object.fromEntries(fields.map(k=>[k,keys.at(-1)[k]]));for(let i=0;i<keys.length-1;i++){let a=keys[i],b=keys[i+1];if(at>=a.time_ms&&at<=b.time_ms){let u=(at-a.time_ms)/(b.time_ms-a.time_ms);if((a.easing||'linear')==='ease-in-out')u=u*u*(3-2*u);if(a.easing==='step')u=0;return Object.fromEntries(fields.map(k=>[k,a[k]+(b[k]-a[k])*u]))}}return defaults}
function opacity(keys,at){return state(keys,at,['opacity'],{opacity:1}).opacity}
function renderShot(s,local,w,h,alpha=1){const im=image(s.art),scale=Math.min(w/im.naturalWidth,h/im.naturalHeight),baseW=im.naturalWidth*scale,baseH=im.naturalHeight*scale,cam=state(s.camera,local,['x','y','zoom'],{x:.5,y:.5,zoom:1});let dw=baseW*cam.zoom,dh=baseH*cam.zoom,x=(w-dw)/2+(0.5-cam.x)*baseW*cam.zoom,y=(h-dh)/2+(0.5-cam.y)*baseH*cam.zoom;ctx.globalAlpha=alpha;ctx.drawImage(im,x,y,dw,dh);for(const id of s.text_ids||[]){const ti=image(s.text_images[id]),op=opacity(s.text?.[id],local);ctx.globalAlpha=alpha*op;ctx.drawImage(ti,(w-baseW)/2,(h-baseH)/2,baseW,baseH)}ctx.globalAlpha=1}
function draw(){const[w,h]=fit();ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);let ix=A.shots.findIndex(s=>t>=s.start_ms&&t<=s.end_ms);if(ix<0&&A.shots.length)ix=A.shots.length-1;if(ix>=0){let s=A.shots[ix],local=Math.min(s.duration_ms,Math.max(0,t-s.start_ms));const tr=s.transition||{type:'cut',duration_ms:0},d=tr.duration_ms||0;if(d&&ix<A.shots.length-1&&t>=s.end_ms-d){let u=(t-(s.end_ms-d))/d,next=A.shots[ix+1];if(tr.type==='dissolve'){renderShot(s,local,w,h,1);renderShot(next,Math.max(0,t-next.start_ms),w,h,u)}else if(tr.type==='fade-through-black'){renderShot(s,local,w,h,Math.max(0,1-2*u));renderShot(next,Math.max(0,t-next.start_ms),w,h,Math.max(0,2*u-1))}else renderShot(s,local,w,h)}else renderShot(s,local,w,h)}seek.value=t;timeOut.textContent=fmt(t)+' / '+fmt(A.duration);requestAnimationFrame(()=>{})}
function fmt(ms){return Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0')}function frame(now){if(!playing)return;if(last)t+=(now-last)*Number(document.querySelector('#speed').value);last=now;if(t>=A.duration){if(document.querySelector('#loop').checked)t%=A.duration;else{t=A.duration;playing=false;play.textContent='Play'}}draw();if(playing)raf=requestAnimationFrame(frame)}
play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play';last=0;if(playing)raf=requestAnimationFrame(frame);else cancelAnimationFrame(raf)};document.querySelector('#restart').onclick=()=>{t=0;draw()};seek.oninput=()=>{t=Number(seek.value);draw()};document.querySelector('#prev').onclick=()=>{let s=[...A.shots].reverse().find(x=>x.start_ms<t-1);t=s?.start_ms||0;draw()};document.querySelector('#next').onclick=()=>{let s=A.shots.find(x=>x.start_ms>t);if(s)t=s.start_ms;draw()};document.querySelector('#full').onclick=()=>canvas.requestFullscreen?.();document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){playing=false;play.textContent='Play';last=0}});window.onresize=draw;document.onkeydown=e=>{if(e.target.matches('input,select,button'))return;if(e.code==='Space'){e.preventDefault();play.click()}else if(e.code==='ArrowRight'){t=Math.min(A.duration,t+5000);draw()}else if(e.code==='ArrowLeft'){t=Math.max(0,t-5000);draw()}};draw();
</script></html>'''
    source=source.replace("__TITLE__",html.escape(resolved_animation.name)).replace("__RATIO__",f"{resolved_animation.aspect_width:g}/{resolved_animation.aspect_height:g}").replace("__DURATION__",str(resolved_animation.duration_ms)).replace("__DATA__",data)
    return source.encode("utf-8")
